/*  Animation                                                          */
/* ------------------------------------------------------------------ */

const lerp = THREE.MathUtils.lerp;

export function animateHero(rig, state, dt) {
  const t = state.time;
  const run = state.moving ? 1 : 0;
  const speedFactor = Math.min(1, state.speed / 8);
  const breathe = Math.sin(t * 2.1) * 0.02;
  const runBob = Math.abs(Math.sin(t * (9 + speedFactor * 4))) * 0.08 * run;

  rig.root.position.y = runBob + (state.dash ? 0.12 : 0);
  rig.torso.rotation.x = lerp(rig.torso.rotation.x, run * 0.12 + breathe, dt * 10);
  rig.torso.rotation.z = lerp(rig.torso.rotation.z, (state.strafe || 0) * -0.05, dt * 8);
  rig.head.rotation.x = lerp(rig.head.rotation.x, state.dash ? -0.18 : 0, dt * 8);

  const stride = Math.sin(t * (10 + speedFactor * 3)) * run;
  rig.leftLeg.hip.rotation.x = lerp(rig.leftLeg.hip.rotation.x, stride * 0.75, dt * 16);
  rig.rightLeg.hip.rotation.x = lerp(rig.rightLeg.hip.rotation.x, -stride * 0.75, dt * 16);
  rig.leftLeg.knee.rotation.x = lerp(rig.leftLeg.knee.rotation.x, Math.max(0, -stride) * 0.9 + run * 0.1, dt * 16);
  rig.rightLeg.knee.rotation.x = lerp(rig.rightLeg.knee.rotation.x, Math.max(0, stride) * 0.9 + run * 0.1, dt * 16);

  // arms
  let rArmX = -stride * 0.7 * run;
  let lArmX = stride * 0.7 * run;
  let rArmZ = -0.1;
  let lArmZ = 0.1;
  let rElbow = -0.15;
  let lElbow = -0.15;

  if (state.attack) {
    const p = state.attackProgress;
    if (state.attackKind === 'heavy') {
      rArmX = -1.3 - Math.sin(p * Math.PI) * 1.15;
      rArmZ = -0.5;
      rElbow = -0.15 - Math.sin(p * Math.PI) * 0.25;
      lArmX = 0.5;
      lArmZ = 0.4;
    } else {
      const swing = Math.sin(p * Math.PI);
      rArmX = -0.6 - swing * 1.5;
      rArmZ = -0.3 - swing * 0.35;
      rElbow = -0.4 + swing * 0.15;
      lArmX = 0.2 + swing * 0.6;
      lArmZ = 0.3;
    }
    rig.torso.rotation.y = lerp(rig.torso.rotation.y, -Math.sin(p * Math.PI) * 0.55, dt * 20);
  } else {
    rig.torso.rotation.y = lerp(rig.torso.rotation.y, 0, dt * 12);
  }

  if (state.dash) {
    rArmX = 0.45; lArmX = 0.45;
    rArmZ = -0.45; lArmZ = 0.45;
    rElbow = -0.9; lElbow = -0.9;
  }

  rig.rightArm.shoulder.rotation.x = lerp(rig.rightArm.shoulder.rotation.x, rArmX, dt * 18);
  rig.leftArm.shoulder.rotation.x = lerp(rig.leftArm.shoulder.rotation.x, lArmX, dt * 18);
  rig.rightArm.shoulder.rotation.z = lerp(rig.rightArm.shoulder.rotation.z, rArmZ, dt * 16);
  rig.leftArm.shoulder.rotation.z = lerp(rig.leftArm.shoulder.rotation.z, lArmZ, dt * 16);
  rig.rightArm.elbow.rotation.x = lerp(rig.rightArm.elbow.rotation.x, rElbow, dt * 18);
  rig.leftArm.elbow.rotation.x = lerp(rig.leftArm.elbow.rotation.x, lElbow, dt * 18);

  const auraStrength = state.blackFlash ? 1 : state.energy / 100;
  rig.aura.material.opacity = 0.16 + auraStrength * 0.2 + (state.blackFlash ? Math.sin(t * 24) * 0.12 : 0);
  rig.auraRing.material.opacity = 0.12 + auraStrength * 0.28;
  rig.auraRing.scale.setScalar(1 + Math.sin(t * 2.4) * 0.06);
}

export function animateEnemy(rig, dt, time, state = {}) {
  const phase = rig.phase || 0;
  if (rig.variant !== undefined) {
    // grunt floats
    const bob = Math.sin(time * 2 + phase) * 0.18;
    rig.root.position.y = rig.floatBase + bob;
    rig.root.rotation.z = Math.sin(time * 1.4 + phase) * 0.04;
    rig.face.rotation.y = Math.sin(time * 0.8 + phase) * 0.12;
    rig.body.rotation.y += dt * 0.3;
    if (rig.light) rig.light.intensity = 2.1 + Math.sin(time * 7 + phase) * 0.6;
  } else if (rig.arms) {
    // boss
    const breathe = Math.sin(time * 1.4) * 0.03;
    rig.root.position.y = 0;
    rig.arms.forEach((arm, i) => {
      const base = i < 2 ? -0.4 : -0.2;
      arm.shoulder.rotation.x = base + Math.sin(time * 1.2 + i * 1.7) * 0.12;
      arm.shoulder.rotation.z = (i % 2 === 0 ? 1 : -1) * (0.22 + Math.sin(time + i) * 0.04);
      arm.elbow.rotation.x = -0.35 + Math.cos(time * 1.4 + i) * 0.1;
    });
    rig.torso.rotation.z = breathe;
    rig.mainFace.rotation.y = Math.sin(time * 0.6) * 0.1;
    rig.aura.scale.setScalar(8.4 + Math.sin(time * 2.2) * 0.7);
    rig.aura2.scale.setScalar(5.6 + Math.cos(time * 1.6) * 0.5);
    if (rig.light) rig.light.intensity = 13 + Math.sin(time * 5) * 4;
  } else {
    // brute
    const walk = Math.sin(time * 4.2 + phase) * (state.moving ? 1 : 0.2);
    rig.leftLeg.hip.rotation.x = walk * 0.55;
    rig.rightLeg.hip.rotation.x = -walk * 0.55;
    rig.leftArm.shoulder.rotation.x = -walk * 0.35 - 0.2;
    rig.rightArm.shoulder.rotation.x = walk * 0.35 - 0.2;
    rig.leftArm.shoulder.rotation.z = 0.18;
    rig.rightArm.shoulder.rotation.z = -0.18;
    rig.head.rotation.y = Math.sin(time * 0.9) * 0.12;
    rig.aura.material.opacity = 0.22 + Math.sin(time * 2.4) * 0.07;
    if (rig.light) rig.light.intensity = 4.4 + Math.sin(time * 4) * 1.3;
  }
}

export function setFlash(rig, amount) {
  if (!rig.flashMats) return;
  rig.flashMats.forEach((m, i) => {
    m.emissive.setStyle(amount > 0 ? '#ff4055' : '#' + rig.baseEmissive[i].getHexString());
    m.emissiveIntensity = amount > 0 ? 1.7 : rig.baseIntensity[i];
    m.color.offsetHSL(0, 0, 0);
  });
}

export function disposeObject(root) {
  root.traverse((o) => {
    if (o.geometry) o.geometry.dispose();
    if (o.material) {
      const mats = Array.isArray(o.material) ? o.material : [o.material];
      mats.forEach((m) => {
        if (m.map && m.map.dispose) m.map.dispose();
        m.dispose();
      });
    }
  });
}

export { glowSprite };

/* Tiny procedural sound engine. No external assets. */
export class SoundEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.musicGain = null;
    this.sfxGain = null;
    this.muted = false;
    this.started = false;
    this.nextPulse = 0;
    this.nextTick = 0;
    this.drone = [];
    this.noiseBuffer = null;
  }

  init() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.muted ? 0 : 0.68;
    this.master.connect(this.ctx.destination);

    this.musicGain = this.ctx.createGain();
    this.musicGain.gain.value = 0.38;
    this.musicGain.connect(this.master);

    this.sfxGain = this.ctx.createGain();
    this.sfxGain.gain.value = 0.9;
    this.sfxGain.connect(this.master);

    // noise buffer reused for impacts and wind
    const len = this.ctx.sampleRate * 1.2;
    this.noiseBuffer = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
    const data = this.noiseBuffer.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;

    this.startAmbient();
    this.started = true;
  }

  startAmbient() {
    const ctx = this.ctx;
    const now = ctx.currentTime;

    // Low, breathing city drone.
    for (const [freq, gain, detune] of [[55, 0.055, 0], [82.41, 0.032, 4], [110, 0.018, -5]]) {
      const osc = ctx.createOscillator();
      osc.type = 'sawtooth';
      osc.frequency.value = freq;
      osc.detune.value = detune;
      const filter = ctx.createBiquadFilter();
      filter.type = 'lowpass';
      filter.frequency.value = 220;
      filter.Q.value = 2;
      const g = ctx.createGain();
      g.gain.value = gain;
      const lfo = ctx.createOscillator();
      const lfoGain = ctx.createGain();
      lfo.frequency.value = 0.06 + Math.random() * 0.08;
      lfoGain.gain.value = gain * 0.55;
      lfo.connect(lfoGain).connect(g.gain);
      lfo.start();
      osc.connect(filter).connect(g).connect(this.musicGain);
      osc.start();
      this.drone.push({ osc, g, lfo });
    }

    // Wind / distant traffic hiss.
    const wind = ctx.createBufferSource();
    wind.buffer = this.noiseBuffer;
    wind.loop = true;
    const windFilter = ctx.createBiquadFilter();
    windFilter.type = 'bandpass';
    windFilter.frequency.value = 340;
    windFilter.Q.value = 0.6;
    const windGain = ctx.createGain();
    windGain.gain.value = 0.035;
    const windLfo = ctx.createOscillator();
    const windLfoGain = ctx.createGain();
    windLfo.frequency.value = 0.08;
    windLfoGain.gain.value = 0.02;
    windLfo.connect(windLfoGain).connect(windGain.gain);
    windLfo.start();
    wind.connect(windFilter).connect(windGain).connect(this.musicGain);
    wind.start();
    this.drone.push({ osc: wind, g: windGain, lfo: windLfo });

    // A distant, lonely bell.
    this.bell(now + 0.4, 146.83, 0.09, 5.5);
  }

  setMuted(muted) {
    this.muted = muted;
    if (this.master) {
      this.master.gain.setTargetAtTime(muted ? 0 : 0.68, this.ctx.currentTime, 0.08);
    }
  }

  toggleMuted() {
    this.setMuted(!this.muted);
    return this.muted;
  }

  now() {
    return this.ctx ? this.ctx.currentTime : 0;
  }

  envGain(level, attack, decay, time = this.now()) {
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, time);
    g.gain.exponentialRampToValueAtTime(Math.max(0.0001, level), time + attack);
    g.gain.exponentialRampToValueAtTime(0.0001, time + attack + decay);
    return g;
  }

  tone({ freq = 220, end = freq, type = 'sine', dur = 0.25, gain = 0.15, delay = 0, filter = 0, q = 1 }) {
    if (!this.ctx || this.muted) return;
    const t = this.now() + delay;
    const osc = this.ctx.createOscillator();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, t);
    osc.frequency.exponentialRampToValueAtTime(Math.max(1, end), t + dur);
    const g = this.envGain(gain, 0.005, dur, t);
    if (filter) {
      const f = this.ctx.createBiquadFilter();
      f.type = 'lowpass';
      f.frequency.value = filter;
      f.Q.value = q;
      osc.connect(f).connect(g).connect(this.sfxGain);
    } else {
      osc.connect(g).connect(this.sfxGain);
    }
    osc.start(t);
    osc.stop(t + dur + 0.05);
  }

  noise({ dur = 0.2, gain = 0.08, freq = 900, endFreq = freq, type = 'bandpass', q = 0.8, delay = 0 }) {
    if (!this.ctx || this.muted) return;
    const t = this.now() + delay;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer;
    const f = this.ctx.createBiquadFilter();
    f.type = type;
    f.frequency.setValueAtTime(freq, t);
    f.frequency.exponentialRampToValueAtTime(Math.max(40, endFreq), t + dur);
    f.Q.value = q;
    const g = this.envGain(gain, 0.004, dur, t);
    src.connect(f).connect(g).connect(this.sfxGain);
    src.start(t);
    src.stop(t + dur + 0.05);
  }

  bell(time, freq = 220, gain = 0.06, dur = 4) {
    if (!this.ctx) return;
    const osc = this.ctx.createOscillator();
    osc.type = 'sine';
    osc.frequency.value = freq;
    const osc2 = this.ctx.createOscillator();
    osc2.type = 'sine';
    osc2.frequency.value = freq * 2.01;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.0001, time);
    g.gain.exponentialRampToValueAtTime(gain, time + 0.02);
    g.gain.exponentialRampToValueAtTime(0.0001, time + dur);
    const g2 = this.ctx.createGain();
    g2.gain.value = 0.35;
    osc.connect(g).connect(this.musicGain);
    osc2.connect(g2).connect(g);
    osc.start(time);
    osc2.start(time);
    osc.stop(time + dur);
    osc2.stop(time + dur);
  }

  whoosh(pitch = 1) {
    this.noise({ dur: 0.16, gain: 0.1, freq: 400 * pitch, endFreq: 2400 * pitch, type: 'bandpass', q: 1.4 });
  }

  hit(heavy = false) {
    this.tone({ freq: heavy ? 160 : 210, end: heavy ? 42 : 66, type: 'sine', dur: heavy ? 0.42 : 0.2, gain: heavy ? 0.36 : 0.22 });
    this.noise({ dur: heavy ? 0.22 : 0.1, gain: heavy ? 0.16 : 0.09, freq: 1400, endFreq: 200, type: 'lowpass', q: 0.8 });
    if (heavy) this.tone({ freq: 90, end: 32, type: 'triangle', dur: 0.5, gain: 0.25, delay: 0.02 });
  }

  blackFlash() {
    if (!this.ctx || this.muted) return;
    this.tone({ freq: 68, end: 23, type: 'sine', dur: 1.8, gain: 0.55 });
    this.tone({ freq: 320, end: 38, type: 'sawtooth', dur: 0.7, gain: 0.16, filter: 880 });
    this.noise({ dur: 0.9, gain: 0.3, freq: 5000, endFreq: 90, type: 'lowpass', q: 0.7 });
    this.noise({ dur: 0.16, gain: 0.34, freq: 6000, endFreq: 1800, type: 'bandpass', q: 0.5 });
    this.bell(this.now() + 0.03, 73.42, 0.16, 5.5);
  }

  hurt() {
    this.tone({ freq: 120, end: 48, type: 'triangle', dur: 0.35, gain: 0.28 });
    this.noise({ dur: 0.16, gain: 0.1, freq: 500, endFreq: 120, type: 'lowpass' });
  }

  enemyDie() {
    this.noise({ dur: 0.5, gain: 0.12, freq: 1800, endFreq: 120, type: 'bandpass', q: 1.1 });
    this.tone({ freq: 140, end: 35, type: 'sawtooth', dur: 0.45, gain: 0.1, filter: 500 });
  }

  waveStart() {
    this.bell(this.now(), 110, 0.18, 6);
    this.tone({ freq: 55, end: 55, type: 'triangle', dur: 2.2, gain: 0.2 });
    this.noise({ dur: 1.2, gain: 0.12, freq: 300, endFreq: 90, type: 'lowpass' });
  }

  victory() {
    if (!this.ctx || this.muted) return;
    [130.81, 164.81, 196, 261.63].forEach((f, i) => {
      this.bell(this.now() + i * 0.45, f, 0.12, 5);
    });
  }

  gameOver() {
    if (!this.ctx || this.muted) return;
    [110, 98, 82.41, 55].forEach((f, i) => {
      this.bell(this.now() + i * 0.42, f, 0.13, 4);
    });
  }

  dash() {
    this.noise({ dur: 0.2, gain: 0.1, freq: 300, endFreq: 1200, type: 'bandpass', q: 1.8 });
  }

  update(dt) {
    if (!this.ctx || !this.started) return;
    const t = this.now();
    if (t > this.nextPulse) {
      this.nextPulse = t + 2.35;
      // deep war drum
      this.tone({ freq: 82, end: 44, type: 'sine', dur: 0.65, gain: 0.12 });
      this.noise({ dur: 0.18, gain: 0.045, freq: 240, endFreq: 80, type: 'lowpass' });
    }
    if (t > this.nextTick) {
      this.nextTick = t + 1.1;
      this.noise({ dur: 0.06, gain: 0.012, freq: 3200, endFreq: 2400, type: 'bandpass', q: 2.5 });
    }
  }
}

@font-face {
  font-family: 'Bebas Neue';
  src: url('fonts/BebasNeue.ttf') format('truetype');
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: 'Rajdhani';
  src: url('fonts/Rajdhani-Regular.ttf') format('truetype');
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: 'Rajdhani';
  src: url('fonts/Rajdhani-SemiBold.ttf') format('truetype');
  font-weight: 600;
  font-display: swap;
}
@font-face {
  font-family: 'Rajdhani';
  src: url('fonts/Rajdhani-Bold.ttf') format('truetype');
  font-weight: 700;
  font-display: swap;
}

:root {
  --ink: #06060b;
  --ink-soft: #0c0c15;
  --paper: #f1e7d6;
  --dim: #948e9e;
  --red: #ff284c;
  --red-deep: #8e1028;
  --gold: #e8bc76;
  --cyan: #69dcff;
  --violet: #a367ff;
  --hud: rgba(9, 9, 15, 0.74);
  --line: rgba(242, 232, 214, 0.18);
  --bebas: 'Bebas Neue', Impact, sans-serif;
  --raj: 'Rajdhani', 'Segoe UI', sans-serif;
}

* { box-sizing: border-box; }
html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--paper);
  font-family: var(--raj);
  overscroll-behavior: none;
  -webkit-user-select: none;
  user-select: none;
}
body { touch-action: none; }

button { font: inherit; color: inherit; cursor: pointer; }
.hidden { display: none !important; }

#game-canvas {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
  background: #05050a;
}

#vignette {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 3;
  background:
    radial-gradient(ellipse at center, transparent 35%, rgba(2, 2, 7, 0.32) 72%, rgba(2, 2, 7, 0.86) 100%),
    linear-gradient(180deg, rgba(0,0,0,.42), transparent 18%, transparent 78%, rgba(0,0,0,.6));
}
#film-grain {
  position: fixed;
  inset: -30%;
  pointer-events: none;
  z-index: 4;
  opacity: 0.045;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.95' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.7'/%3E%3C/svg%3E");
  animation: grainShift 0.28s steps(2) infinite;
  mix-blend-mode: screen;
}
@keyframes grainShift {
  0% { transform: translate(0, 0); }
  25% { transform: translate(-3%, 2%); }
  50% { transform: translate(2%, -4%); }
  75% { transform: translate(-1%, -2%); }
  100% { transform: translate(3%, 3%); }
}

#cinema-bars i {
  position: fixed;
  left: 0;
  right: 0;
  height: 2.2vh;
  background: #000;
  z-index: 20;
  pointer-events: none;
}
#cinema-bars i:first-child { top: 0; }
#cinema-bars i:last-child { bottom: 0; }

#damage-overlay {
  position: fixed;
  inset: 0;
  z-index: 6;
  pointer-events: none;
  opacity: 0;
  background:
    radial-gradient(ellipse at center, transparent 30%, rgba(255, 18, 50, .32) 72%, rgba(120, 0, 16, .75) 100%);
  transition: opacity 0.16s ease-out;
  mix-blend-mode: screen;
}
#flash-overlay {
  position: fixed;
  inset: 0;
  z-index: 5;
  pointer-events: none;
  opacity: 0;
  background: #fff;
}
#flash-overlay.red { background: #ff1735; }
#flash-overlay.black { background: #050106; }
#flash-overlay.flash { animation: whiteFlash 0.35s ease-out forwards; }
@keyframes whiteFlash {
  0% { opacity: .92; }
  25% { opacity: .25; }
  100% { opacity: 0; }
}

/* ======================= LOADER ======================= */
#loader {
  position: fixed;
  inset: 0;
  z-index: 200;
  background: #050509;
  display: grid;
  place-content: center;
  justify-items: center;
  gap: 30px;
  transition: opacity .8s ease .1s, visibility .8s ease .1s;
}
#loader.done { opacity: 0; visibility: hidden; }
.loader-mark {
  width: 100px;
  height: 100px;
  border: 1px solid rgba(255, 40, 76, .45);
  display: grid;
  place-items: center;
  font-family: serif;
  font-size: 50px;
  color: var(--red);
  transform: rotate(45deg);
  text-shadow: 0 0 24px var(--red);
  animation: markPulse 2s ease-in-out infinite;
}
.loader-mark::first-letter { transform: rotate(-45deg); }
@keyframes markPulse { 50% { box-shadow: 0 0 34px rgba(255,40,76,.2), inset 0 0 20px rgba(255,40,76,.1); border-color: rgba(255,40,76,.8); } }
.loader-copy { display: flex; flex-direction: column; gap: 10px; align-items: center; font-size: 10px; letter-spacing: .36em; color: #a7a0af; }
.loader-line { width: 230px; height: 2px; background: rgba(255,255,255,.12); overflow: hidden; }
.loader-line i { display: block; height: 100%; width: 38%; background: var(--red); animation: load 1.4s cubic-bezier(.6,0,.2,1) infinite; box-shadow: 0 0 12px var(--red); }
@keyframes load { 0% { transform: translateX(-120%); } 100% { transform: translateX(320%); } }

/* ======================= SCREENS ======================= */
.screen {
  position: fixed;
  inset: 0;
  z-index: 30;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity .5s ease, visibility .5s ease;
}
.screen.is-visible {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

/* ======================= MENU ======================= */
#menu {
  display: flex;
  flex-direction: column;
  justify-content: center;
  background:
    linear-gradient(90deg, rgba(3,3,8,.94) 0%, rgba(3,3,8,.72) 38%, rgba(3,3,8,.05) 72%),
    linear-gradient(180deg, rgba(3,3,8,.62), transparent 28%, transparent 70%, rgba(3,3,8,.9));
  overflow: hidden;
}
#menu::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 70% 46%, transparent 10%, rgba(5,5,10,.3) 60%, rgba(5,5,10,.88));
  pointer-events: none;
}
#menu::after {
  content: '呪';
  position: absolute;
  right: 8vw;
  top: 40%;
  transform: translateY(-50%) rotate(3deg);
  font-family: serif;
  font-size: min(50vw, 600px);
  line-height: 1;
  color: transparent;
  -webkit-text-stroke: 1px rgba(255, 40, 76, .1);
  pointer-events: none;
}
.menu-rail { position: absolute; top: 0; bottom: 0; width: 1px; background: linear-gradient(transparent, rgba(255,40,76,.35), transparent); }
.menu-rail.left { left: 34px; }
.menu-rail.right { right: 34px; }
.menu-rail::before, .menu-rail::after { content: ''; position: absolute; width: 5px; height: 5px; background: var(--red); border-radius: 50%; box-shadow: 0 0 10px var(--red); }
.menu-rail::before { top: 16%; left: -2px; }
.menu-rail::after { bottom: 14%; left: -2px; }

.menu-content {
  position: relative;
  z-index: 2;
  width: min(1480px, calc(100% - 130px));
  margin: 0 auto;
  display: grid;
  grid-template-columns: minmax(500px, 1fr) 330px;
  gap: 60px;
  align-items: center;
  padding: 4vh 0 8vh;
}
.menu-main { max-width: 740px; }

.eyebrow {
  display: flex;
  align-items: center;
  gap: 12px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .28em;
  color: #c1bac8;
  margin-bottom: 8px;
  text-transform: uppercase;
}
.eyebrow b { color: var(--red); font-weight: 400; }
.pulse-dot {
  width: 7px; height: 7px; border-radius: 50%;
  background: var(--red); box-shadow: 0 0 0 0 rgba(255,40,76,.6);
  animation: pulseDot 1.8s infinite;
}
@keyframes pulseDot { 70% { box-shadow: 0 0 0 8px rgba(255,40,76,0); } 100% { box-shadow: 0 0 0 0 rgba(255,40,76,0); } }

.logo { margin: 0; position: relative; line-height: .78; }
.logo-jp {
  position: absolute;
  left: -3.3vw;
  top: 2.3vw;
  writing-mode: vertical-rl;
  font-family: serif;
  font-size: clamp(26px, 3.2vw, 50px);
  letter-spacing: .15em;
  color: var(--red);
  opacity: .85;
  text-shadow: 0 0 26px rgba(255,40,76,.5);
  line-height: 1;
}
.logo-main {
  display: block;
  font-family: var(--bebas);
  font-size: clamp(78px, 11.5vw, 172px);
  letter-spacing: .025em;
  color: var(--paper);
  text-shadow:
    0 0 60px rgba(255, 255, 255, .06),
    3px 3px 0 rgba(95, 8, 24, .18);
  -webkit-text-stroke: 1px rgba(255,255,255,.05);
}
.logo-sub {
  display: block;
  font-family: var(--bebas);
  font-size: clamp(34px, 5vw, 76px);
  letter-spacing: .48em;
  color: var(--red);
  text-shadow: 0 0 34px rgba(255, 40, 76, .26);
  margin-top: .08em;
  padding-left: .12em;
}
.logo-sub i {
  font-style: normal;
  -webkit-text-stroke: 1px var(--red);
  color: transparent;
  text-shadow: none;
}
.tagline {
  font-size: clamp(14px, 1.2vw, 18px);
  line-height: 1.55;
  letter-spacing: .06em;
  color: #b6b0bd;
  border-left: 2px solid var(--red);
  padding-left: 18px;
  margin: 26px 0 30px;
}
.tagline br + * { color: #7e7888; }

.menu-actions { display: flex; align-items: stretch; gap: 14px; }
.btn-primary {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: center;
  min-width: 320px;
  padding: 15px 68px 14px 26px;
  border: 0;
  background: linear-gradient(100deg, #c11a37, var(--red));
  color: #fff;
  text-align: left;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 15px), calc(100% - 15px) 100%, 0 100%);
  box-shadow: 0 0 38px rgba(255, 32, 71, .24);
  transition: transform .2s ease, filter .2s ease;
  overflow: hidden;
}
.btn-primary::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(110deg, transparent 30%, rgba(255,255,255,.24) 50%, transparent 70%);
  transform: translateX(-110%);
  transition: transform .55s ease;
}
.btn-primary:hover { transform: translateY(-2px); filter: brightness(1.12); }
.btn-primary:hover::before { transform: translateX(110%); }
.btn-kicker { font-size: 9px; letter-spacing: .25em; opacity: .75; margin-bottom: 4px; }
.btn-label { font-family: var(--bebas); font-size: 30px; letter-spacing: .16em; line-height: 1; }
.btn-arrow { position: absolute; right: 26px; top: 50%; transform: translateY(-50%); font-size: 30px; font-weight: 300; transition: transform .2s ease; }
.btn-primary:hover .btn-arrow { transform: translate(5px, -50%); }
.btn-ghost {
  background: transparent;
  border: 1px solid rgba(242,232,214,.24);
  padding: 0 22px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: .22em;
  color: #bcb5c3;
  transition: all .2s ease;
}
.btn-ghost:hover { border-color: var(--red); color: #fff; background: rgba(255,40,76,.08); }
.btn-primary.compact { min-width: 250px; width: 100%; margin-top: 14px; }

.control-strip {
  display: flex;
  gap: 25px;
  margin-top: 30px;
  padding-top: 19px;
  border-top: 1px solid rgba(255,255,255,.1);
  flex-wrap: wrap;
}
.control-strip > div { display: flex; align-items: center; gap: 8px; font-size: 9px; letter-spacing: .18em; color: #77717e; }
.control-strip kbd, .hint-line kbd, .pause-controls kbd, .how-grid kbd {
  font-family: var(--raj);
  font-size: 10px;
  font-weight: 700;
  letter-spacing: .08em;
  color: #e9e1d4;
  border: 1px solid rgba(255,255,255,.25);
  background: rgba(255,255,255,.06);
  padding: 3px 7px;
  min-width: 26px;
  text-align: center;
}

.mission-card {
  position: relative;
  padding: 24px 25px 22px;
  background: linear-gradient(155deg, rgba(15,15,24,.88), rgba(8,8,14,.7));
  border: 1px solid rgba(255,255,255,.12);
  border-top: 2px solid rgba(255,40,76,.7);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 22px), calc(100% - 22px) 100%, 0 100%);
  backdrop-filter: blur(8px);
  box-shadow: 0 20px 70px rgba(0,0,0,.4);
}
.mission-head { display: flex; justify-content: space-between; font-size: 9px; letter-spacing: .25em; color: #8d8694; border-bottom: 1px solid rgba(255,255,255,.1); padding-bottom: 11px; }
.mission-head b { color: var(--red); font-size: 11px; }
.mission-glyph {
  position: absolute;
  right: 20px;
  top: 54px;
  font-family: serif;
  font-size: 84px;
  line-height: 1;
  color: rgba(255,40,76,.12);
  border: 1px solid rgba(255,40,76,.13);
  padding: 2px 10px 8px;
}
.mission-card h2 { font-family: var(--bebas); font-size: 28px; font-weight: 400; letter-spacing: .09em; margin: 22px 0 9px; color: #f2e9da; }
.mission-card p { font-size: 12px; line-height: 1.55; color: #9d95a6; margin: 0 0 19px; max-width: 90%; }
.mission-card ul { list-style: none; margin: 0; padding: 0; border-top: 1px solid rgba(255,255,255,.08); }
.mission-card li { display: flex; gap: 12px; align-items: center; font-size: 10px; letter-spacing: .09em; color: #aaa2b1; padding: 8px 0; border-bottom: 1px solid rgba(255,255,255,.055); }
.mission-card li span { font-family: var(--bebas); font-size: 15px; color: var(--red); }
.mission-footer { display: flex; justify-content: space-between; align-items: center; margin-top: 18px; font-size: 8px; letter-spacing: .26em; color: #827b8a; }
.mission-footer b { font-size: 10px; color: var(--gold); letter-spacing: .22em; }
.menu-bottom {
  position: absolute;
  bottom: 3.2vh;
  left: 60px;
  right: 60px;
  display: flex;
  justify-content: space-between;
  font-size: 8px;
  letter-spacing: .2em;
  color: #5b5662;
  z-index: 2;
}
.headphones { display: inline-grid; place-items: center; width: 14px; height: 14px; border: 1px solid #5b5662; border-radius: 50%; margin-left: 5px; font-style: normal; font-size: 8px; }

/* ======================= HUD ======================= */
#hud { transition: opacity .35s ease; }
#hud.fade { opacity: .2; }
.hud-top { position: absolute; top: 4.2vh; left: 38px; right: 38px; display: flex; align-items: flex-start; justify-content: space-between; }
.hud-brand { display: flex; align-items: baseline; gap: 9px; }
.hud-brand span { font-family: serif; font-size: 24px; color: var(--red); text-shadow: 0 0 18px rgba(255,40,76,.55); }
.hud-brand b { font-family: var(--bebas); font-size: 22px; letter-spacing: .14em; font-weight: 400; }
.hud-brand i { font-size: 8px; letter-spacing: .2em; color: #706a7c; font-style: normal; }
.wave-chip { display: flex; align-items: baseline; gap: 6px; padding: 5px 14px 7px; background: rgba(5,5,10,.55); border: 1px solid rgba(255,255,255,.1); clip-path: polygon(8px 0, 100% 0, calc(100% - 8px) 100%, 0 100%); }
.wave-kicker { font-size: 9px; letter-spacing: .28em; color: #8c8597; }
#wave-num { font-family: var(--bebas); font-size: 26px; line-height: 1; color: #fff; }
.wave-chip em { font-style: normal; font-size: 11px; color: #716b7c; }
.wave-pip { width: 54px; height: 2px; background: rgba(255,255,255,.15); margin-left: 10px; overflow: hidden; align-self: center; }
.wave-pip i { display: block; width: 20%; height: 100%; background: var(--red); box-shadow: 0 0 8px var(--red); transition: width .5s ease; }
.score-box { text-align: right; }
.score-box span { display: block; font-size: 8px; letter-spacing: .28em; color: #837c90; margin-bottom: 1px; }
.score-box b { font-family: var(--bebas); font-weight: 400; font-size: 25px; letter-spacing: .1em; color: #eae2d4; }

.objective-panel { position: absolute; top: 10.5vh; left: 38px; padding-left: 13px; border-left: 2px solid var(--red); max-width: 320px; }
.obj-kicker { display: block; font-size: 8px; letter-spacing: .26em; color: var(--red); margin-bottom: 3px; }
.objective-panel strong { display: block; font-family: var(--bebas); font-weight: 400; font-size: 18px; letter-spacing: .1em; color: #eae2d4; }
.objective-panel p { margin: 2px 0 0; color: #878090; font-size: 10px; letter-spacing: .08em; }

.player-hud { position: absolute; left: 38px; bottom: 7vh; display: flex; align-items: flex-end; gap: 14px; }
.sigil { position: relative; width: 62px; height: 62px; border: 1px solid rgba(255,40,76,.45); display: grid; place-items: center; transform: rotate(45deg); background: rgba(8,8,14,.72); box-shadow: 0 0 28px rgba(255,40,76,.1); }
.sigil::after { content: ''; position: absolute; inset: 5px; border: 1px solid rgba(255,255,255,.12); }
.sigil span { transform: rotate(-45deg); font-family: serif; font-size: 27px; color: var(--red); text-shadow: 0 0 14px rgba(255,40,76,.8); }
.sigil i { position: absolute; width: 5px; height: 5px; background: var(--red); border-radius: 50%; top: -3px; left: -3px; box-shadow: 0 0 8px var(--red); }
.player-bars { width: clamp(260px, 27vw, 390px); }
.player-name { display: flex; align-items: baseline; gap: 9px; margin-bottom: 7px; }
.player-name b { font-family: var(--bebas); font-weight: 400; letter-spacing: .16em; font-size: 19px; color: #f0e5d2; }
.player-name span { font-size: 7px; letter-spacing: .2em; color: #777081; }
.bar { display: flex; align-items: center; gap: 8px; margin-top: 5px; }
.bar-label { width: 69px; font-size: 7px; letter-spacing: .15em; color: #7f7889; text-align: right; }
.bar-track { position: relative; flex: 1; height: 9px; background: rgba(255,255,255,.1); border: 1px solid rgba(255,255,255,.08); overflow: hidden; }
.bar-track::after { content: ''; position: absolute; inset: 0; background: repeating-linear-gradient(90deg, transparent 0 28px, rgba(0,0,0,.4) 28px 30px); }
.bar-track i { display: block; height: 100%; transition: width .15s ease-out; }
.bar.hp .bar-track i { width: 100%; background: linear-gradient(90deg, #8d0f29, #ff284c); box-shadow: 0 0 12px rgba(255,40,76,.55); }
.bar.ce .bar-track { height: 6px; }
.bar.ce .bar-track i { width: 0%; background: linear-gradient(90deg, #4b2cc6, #9f5dff 70%, #f0d6ff); box-shadow: 0 0 12px rgba(163,103,255,.6); }
.bar > b { width: 24px; font-size: 9px; color: #8f8898; font-weight: 600; }
.ultimate-ready {
  margin-top: 8px;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: .22em;
  color: var(--gold);
  border: 1px solid rgba(232,188,118,.34);
  padding: 4px 8px;
  background: rgba(232,188,118,.08);
  opacity: 0;
  transform: translateY(4px);
  transition: all .25s ease;
}
.ultimate-ready.on { opacity: 1; transform: none; animation: readyPulse 1.2s ease-in-out infinite; }
.ultimate-ready kbd { padding: 1px 4px; border-color: rgba(232,188,118,.5); color: var(--gold); font-size: 8px; }
@keyframes readyPulse { 50% { box-shadow: 0 0 22px rgba(232,188,118,.2); } }

.combo-wrap { position: absolute; right: 6vw; top: 33vh; pointer-events: none; }
.combo { text-align: right; opacity: 0; transform: translateX(18px); transition: opacity .2s, transform .2s; }
.combo.on { opacity: 1; transform: none; }
.combo b { display: block; font-family: var(--bebas); font-size: clamp(56px, 7vw, 104px); line-height: .8; font-weight: 400; color: #fff; text-shadow: 0 0 36px rgba(255,40,76,.4); }
.combo span { font-size: 9px; letter-spacing: .3em; color: #b5adbd; }
.combo i { display: block; width: 34px; height: 2px; background: var(--red); margin: 8px 0 0 auto; box-shadow: 0 0 9px var(--red); }
.combo i::after { content: attr(data-rank); }

.boss-panel { position: absolute; left: 50%; bottom: 11.5vh; transform: translateX(-50%); width: min(620px, 55vw); }
.boss-head { display: flex; justify-content: space-between; align-items: baseline; margin-bottom: 5px; }
.boss-head span { font-size: 8px; letter-spacing: .3em; color: var(--red); }
.boss-head b { font-family: var(--bebas); font-weight: 400; font-size: 18px; letter-spacing: .13em; color: #ded2c0; }
.boss-track { height: 11px; background: rgba(255,255,255,.09); border: 1px solid rgba(255,40,76,.2); padding: 2px; }
.boss-track i { display: block; width: 100%; height: 100%; background: linear-gradient(90deg, #581022, #ff284c 60%, #ff7f68); box-shadow: 0 0 18px rgba(255,40,76,.5); transition: width .2s ease; }

.kill-feed { position: absolute; right: 38px; top: 16vh; display: flex; flex-direction: column; gap: 5px; align-items: flex-end; }
.kill-item { font-size: 9px; letter-spacing: .12em; color: #b9b0c1; background: rgba(7,7,12,.54); border-right: 2px solid var(--red); padding: 4px 8px; animation: feedIn .25s ease-out, feedOut .4s ease-in 2.6s forwards; }
.kill-item b { color: var(--red); }
@keyframes feedIn { from { opacity: 0; transform: translateX(15px); } }
@keyframes feedOut { to { opacity: 0; transform: translateX(10px); } }

.hud-bottom { position: absolute; bottom: 3.2vh; right: 38px; display: flex; align-items: center; gap: 13px; }
.hint-line { font-size: 8px; letter-spacing: .12em; color: #777181; margin-right: 5px; }
.hint-line kbd { padding: 1px 5px; font-size: 8px; }
.hint-line span { margin: 0 7px; color: #4e4a57; }
.icon-btn { background: rgba(8,8,14,.45); border: 1px solid rgba(255,255,255,.15); color: #948c9e; font-size: 8px; letter-spacing: .16em; padding: 7px 10px; transition: all .2s; }
.icon-btn:hover { border-color: var(--red); color: #fff; }
.pause-btn { width: 31px; height: 31px; padding: 0; font-size: 12px; letter-spacing: 0; }
.reticle { position: absolute; left: 50%; top: 50%; width: 16px; height: 16px; transform: translate(-50%,-50%); pointer-events: none; opacity: .6; }
.reticle i { position: absolute; left: 50%; top: 50%; width: 3px; height: 3px; border-radius: 50%; background: #fff; box-shadow: 0 0 5px rgba(255,255,255,.7); transform: translate(-50%,-50%); }

/* ======================= WAVE BANNER ======================= */
.wave-banner {
  position: fixed;
  left: 50%;
  top: 42%;
  transform: translate(-50%,-50%) scale(.97);
  z-index: 35;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  opacity: 0;
  pointer-events: none;
  width: min(680px, 70vw);
}
.wave-banner.show { animation: bannerIn 3.2s ease forwards; }
@keyframes bannerIn {
  0% { opacity: 0; transform: translate(-50%,-50%) scale(1.06); filter: blur(5px); }
  12% { opacity: 1; transform: translate(-50%,-50%) scale(1); filter: none; }
  80% { opacity: 1; }
  100% { opacity: 0; transform: translate(-50%,-52%) scale(.99); }
}
.wb-line { width: 100%; height: 1px; background: linear-gradient(90deg, transparent, rgba(255,40,76,.75), transparent); margin: 12px 0; }
#wb-kicker { font-size: 10px; letter-spacing: .5em; color: var(--red); text-shadow: 0 0 18px rgba(255,40,76,.5); }
.wave-banner strong { font-family: var(--bebas); font-weight: 400; font-size: clamp(35px, 5vw, 68px); letter-spacing: .1em; color: #f5ead8; line-height: 1.05; margin: 4px 0 2px; }
.wave-banner em { font-style: normal; font-size: 10px; letter-spacing: .28em; color: #a299ad; text-transform: uppercase; }

.announcement { position: fixed; left: 50%; top: 63%; transform: translateX(-50%); z-index: 34; pointer-events: none; }
.announcement.show span { display: block; font-size: 10px; letter-spacing: .3em; color: var(--gold); background: rgba(6,6,11,.65); border: 1px solid rgba(232,188,118,.3); padding: 7px 15px; animation: announce 2.5s ease forwards; }
@keyframes announce { 0% { opacity: 0; transform: translateY(8px); } 12%,72% { opacity: 1; transform: none; } 100% { opacity: 0; transform: translateY(-8px); } }

#floating-layer { position: fixed; inset: 0; pointer-events: none; z-index: 12; overflow: hidden; }
.float-number { position: absolute; font-family: var(--bebas); font-size: 22px; color: #fff; text-shadow: 0 0 8px rgba(255,40,76,.7); transform: translate(-50%,-50%); will-change: transform, opacity; letter-spacing: .04em; }
.float-number.crit { color: var(--gold); font-size: 36px; text-shadow: 0 0 16px rgba(232,188,118,.8); }

/* ======================= BLACK FLASH OVERLAY ======================= */
#domain-overlay { position: fixed; inset: 0; z-index: 25; pointer-events: none; opacity: 0; display: grid; place-items: center; background: radial-gradient(circle, rgba(60,0,9,.18), rgba(0,0,0,.82)); mix-blend-mode: normal; }
#domain-overlay.on { animation: domainReveal 1.9s ease forwards; }
@keyframes domainReveal {
  0% { opacity: 0; }
  8% { opacity: 1; }
  24% { opacity: .82; }
  67% { opacity: .9; }
  100% { opacity: 0; }
}
.domain-text { text-align: center; transform: scale(1.2); }
#domain-overlay.on .domain-text { animation: domainZoom 1.9s cubic-bezier(.2,.7,.2,1) forwards; }
@keyframes domainZoom { 0% { transform: scale(1.35); filter: blur(9px); } 18% { transform: scale(1); filter: none; } 80% { transform: scale(1.02); } 100% { transform: scale(1.1); opacity: 0; } }
.domain-text span { display: block; font-family: serif; font-size: 12px; letter-spacing: .8em; color: var(--red); margin-bottom: 13px; }
.domain-text strong { display: block; font-family: var(--bebas); font-weight: 400; font-size: clamp(70px, 13vw, 180px); line-height: .72; letter-spacing: .04em; color: #f6ead8; text-shadow: 6px 6px 0 rgba(130,0,18,.4), 0 0 70px rgba(255,20,50,.25); }
.domain-text em { display: block; font-style: normal; color: #9d92a2; letter-spacing: .4em; font-size: 10px; margin-top: 20px; }

/* ======================= MODALS ======================= */
.modal-screen { display: grid; place-items: center; background: rgba(3,3,8,.68); backdrop-filter: blur(7px) saturate(.7); }
.modal-card, .how-card {
  position: relative;
  width: min(460px, calc(100vw - 38px));
  padding: 38px 38px 32px;
  background: linear-gradient(160deg, rgba(17,17,28,.96), rgba(7,7,13,.96));
  border: 1px solid rgba(255,255,255,.13);
  border-top: 2px solid var(--red);
  box-shadow: 0 35px 100px rgba(0,0,0,.7);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 28px), calc(100% - 28px) 100%, 0 100%);
  text-align: center;
}
.modal-kicker { font-size: 8px; letter-spacing: .38em; color: var(--red); }
.modal-card h2, .how-card h2, .result-card h2 { font-family: var(--bebas); font-weight: 400; font-size: 58px; letter-spacing: .08em; line-height: 1; margin: 10px 0 8px; }
.modal-card p { color: #8d8596; font-size: 12px; letter-spacing: .1em; margin-bottom: 20px; }
.modal-card .btn-primary, .how-card .btn-primary { align-items: center; text-align: center; }
.modal-card .btn-arrow { display: none; }
.pause-controls { display: grid; grid-template-columns: 1fr 1fr; gap: 7px; margin-top: 24px; border-top: 1px solid rgba(255,255,255,.1); padding-top: 16px; font-size: 8px; letter-spacing: .13em; color: #7e7788; }
.pause-controls kbd { margin-right: 4px; }

/* ======================= RESULT ======================= */
.result-screen { background: radial-gradient(circle at 50% 35%, rgba(42,10,19,.6), rgba(3,3,8,.92) 60%); }
.result-bg { position: absolute; inset: 0; background: repeating-linear-gradient(90deg, transparent 0 80px, rgba(255,40,76,.025) 80px 81px); }
.result-card { position: relative; width: min(570px, calc(100vw - 34px)); text-align: center; padding: 36px 45px 32px; background: linear-gradient(165deg, rgba(19,16,25,.97), rgba(6,6,11,.98)); border: 1px solid rgba(255,255,255,.12); border-top: 2px solid var(--red); clip-path: polygon(0 0, 100% 0, 100% calc(100% - 30px), calc(100% - 30px) 100%, 0 100%); box-shadow: 0 40px 120px rgba(0,0,0,.8); }
.result-card h2 { font-size: 66px; margin-top: 4px; background: linear-gradient(180deg, #fff4df, #d7c4ab); -webkit-background-clip: text; background-clip: text; color: transparent; }
.result-card p { color: #928998; font-size: 12px; letter-spacing: .08em; margin: 0 0 20px; }
.grade-wrap { display: flex; align-items: center; justify-content: center; gap: 33px; margin: 14px 0 16px; }
.grade-ring { width: 126px; height: 126px; border: 1px solid rgba(232,188,118,.45); border-radius: 50%; display: flex; flex-direction: column; align-items: center; justify-content: center; position: relative; box-shadow: 0 0 50px rgba(232,188,118,.1), inset 0 0 30px rgba(232,188,118,.07); }
.grade-ring::after { content: ''; position: absolute; inset: 9px; border: 1px dashed rgba(232,188,118,.24); border-radius: 50%; }
.grade-ring span { font-size: 8px; letter-spacing: .3em; color: #9d8f83; z-index: 1; }
.grade-ring b { font-family: var(--bebas); font-size: 65px; line-height: .8; font-weight: 400; color: var(--gold); text-shadow: 0 0 27px rgba(232,188,118,.35); z-index: 1; }
.result-stats { display: grid; grid-template-columns: 1fr 1fr; gap: 12px 28px; text-align: left; }
.result-stats div { border-left: 1px solid rgba(255,255,255,.13); padding-left: 11px; }
.result-stats span { display: block; font-size: 7px; letter-spacing: .22em; color: #7d7587; margin-bottom: 2px; }
.result-stats b { font-family: var(--bebas); font-weight: 400; font-size: 22px; letter-spacing: .06em; color: #e7ddcc; }
.result-line { font-family: serif; font-size: 11px; color: #8f8291; border-top: 1px solid rgba(255,255,255,.1); border-bottom: 1px solid rgba(255,255,255,.1); padding: 11px 0; margin: 7px 0 15px; }
.result-card .btn-primary { align-items: center; text-align: center; }
.result-card .btn-arrow { display: none; }

/* ======================= HOW TO ======================= */
.how-card { width: min(780px, calc(100vw - 34px)); padding: 35px 38px 30px; text-align: left; }
.how-card h2 { font-size: 52px; margin: 6px 0 18px; }
.how-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px 22px; }
.how-grid > div { border-top: 1px solid rgba(255,255,255,.1); padding-top: 11px; }
.how-grid kbd { display: inline-block; margin-bottom: 7px; color: var(--red); border-color: rgba(255,40,76,.28); background: rgba(255,40,76,.06); }
.how-grid h3 { font-family: var(--bebas); font-size: 20px; font-weight: 400; letter-spacing: .12em; margin: 0 0 4px; color: #eee2cf; }
.how-grid p { font-size: 10px; line-height: 1.45; color: #8a8292; margin: 0; }
.how-tip { font-size: 10px; line-height: 1.5; letter-spacing: .03em; color: #9c8; color: #9d91a2; border-left: 2px solid var(--gold); padding-left: 11px; margin: 22px 0; }
.how-card .btn-primary { width: 230px; margin: 0 auto; }

/* ======================= MOBILE ======================= */
.mobile-controls { display: none; position: fixed; inset: 0; z-index: 18; pointer-events: none; }
.joystick {
  position: absolute;
  left: max(22px, env(safe-area-inset-left));
  bottom: max(28px, env(safe-area-inset-bottom));
  width: 124px;
  height: 124px;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,.22);
  background: rgba(9,9,15,.28);
  pointer-events: auto;
  touch-action: none;
  backdrop-filter: blur(3px);
}
.joystick::before, .joystick::after { content: ''; position: absolute; background: rgba(255,255,255,.13); }
.joystick::before { left: 50%; top: 14px; bottom: 14px; width: 1px; }
.joystick::after { top: 50%; left: 14px; right: 14px; height: 1px; }
.joystick > span { position: absolute; bottom: -18px; width: 100%; text-align: center; font-size: 7px; letter-spacing: .25em; color: #736d7e; }
.knob { position: absolute; left: 50%; top: 50%; width: 52px; height: 52px; border-radius: 50%; background: radial-gradient(circle at 35% 30%, rgba(255,70,95,.7), rgba(91,11,29,.65)); border: 1px solid rgba(255,90,110,.5); transform: translate(-50%,-50%); box-shadow: 0 0 25px rgba(255,40,76,.22); display: grid; place-items: center; }
.knob i { width: 5px; height: 5px; border-radius: 50%; background: #ffd8d8; box-shadow: 0 0 8px #fff; }
.mobile-actions { position: absolute; right: max(18px, env(safe-area-inset-right)); bottom: max(26px, env(safe-area-inset-bottom)); width: 190px; height: 190px; pointer-events: auto; }
.m-btn { position: absolute; border-radius: 50%; border: 1px solid rgba(255,255,255,.25); background: rgba(10,10,17,.5); color: #e9dfd0; font-family: var(--bebas); letter-spacing: .1em; touch-action: none; backdrop-filter: blur(4px); transition: transform .08s, background .08s; }
.m-btn:active, .m-btn.down { transform: scale(.91); background: rgba(255,40,76,.4); }
.m-btn small { display: block; font-family: var(--raj); font-size: 6px; letter-spacing: .12em; color: #b6adbc; }
.m-btn.attack { width: 87px; height: 87px; right: 11px; bottom: 10px; font-size: 18px; background: rgba(150,15,38,.6); border-color: rgba(255,80,104,.5); }
.m-btn.heavy { width: 66px; height: 66px; right: 91px; bottom: 73px; font-size: 12px; }
.m-btn.dash { width: 58px; height: 58px; right: 16px; bottom: 104px; font-size: 11px; }
.m-btn.ult { width: 62px; height: 62px; right: 92px; bottom: 8px; font-size: 17px; border-color: rgba(232,188,118,.45); color: var(--gold); opacity: .45; }
.m-btn.ult.ready { opacity: 1; box-shadow: 0 0 24px rgba(232,188,118,.32); animation: readyPulse 1.1s infinite; }

#rotate-notice { display: none; position: fixed; left: 50%; bottom: 12px; transform: translateX(-50%); z-index: 100; font-size: 8px; letter-spacing: .18em; color: #827a8e; }

/* ======================= RESPONSIVE ======================= */
@media (max-width: 1100px) {
  .menu-content { grid-template-columns: 1fr 290px; gap: 30px; width: calc(100% - 100px); }
  .logo-main { font-size: clamp(75px, 13vw, 140px); }
  .logo-sub { font-size: clamp(30px, 5.2vw, 58px); letter-spacing: .35em; }
}

@media (max-width: 860px), (pointer: coarse) {
  .mission-card { display: none; }
  .menu-content { grid-template-columns: 1fr; width: calc(100% - 44px); padding: 0; }
  .menu-main { max-width: 580px; }
  #menu { justify-content: center; background: linear-gradient(90deg, rgba(3,3,8,.92), rgba(3,3,8,.65) 55%, rgba(3,3,8,.18)); }
  .logo-jp { left: -22px; top: 26px; opacity: .55; }
  .logo-main { font-size: clamp(64px, 18vw, 120px); }
  .logo-sub { font-size: clamp(28px, 8vw, 52px); letter-spacing: .28em; }
  .tagline { margin: 20px 0 24px; font-size: 13px; }
  .menu-actions { flex-direction: column; align-items: stretch; max-width: 420px; }
  .btn-primary { min-width: 0; width: 100%; }
  .btn-ghost { padding: 13px; }
  .control-strip { display: none; }
  .menu-bottom { left: 22px; right: 22px; bottom: 2.6vh; font-size: 6px; }
  .menu-bottom span:last-child { display: none; }
  .menu-rail { display: none; }
  .mobile-controls { display: block; }
  .hud-top { top: max(3.5vh, env(safe-area-inset-top)); left: 16px; right: 16px; }
  .hud-brand i { display: none; }
