    const a = Math.random() * Math.PI * 2;
    const pts = [];
    let x = center.x;
    let z = center.z;
    let y = 0.1 + Math.random() * 0.4;
    pts.push(new THREE.Vector3(x, y, z));
    for (let j = 0; j < 6; j++) {
      x += Math.cos(a + (Math.random() - 0.5) * 1.4) * (1.5 + Math.random() * 3);
      z += Math.sin(a + (Math.random() - 0.5) * 1.4) * (1.5 + Math.random() * 3);
