const page = await browser.newPage({viewport:{width:1024,height:640}});
page.on('pageerror', e => console.log('PAGEERROR', e.message));
page.on('console', m => { if (m.type() === 'error') console.log('CONSOLE', m.text()); });
await page.goto('http://localhost:3002?quality=low', {waitUntil:'load'});
await page.waitForTimeout(1500);
await page.click('#start-btn');
await page.waitForTimeout(500);
console.log('start', await page.evaluate(()=>window.__JJK.state));

for (let w = 1; w <= 5; w++) {
  await page.evaluate((n)=>window.__JJK.jumpWave(n), w);
  await page.waitForTimeout(2500);
  const before = await page.evaluate(()=>window.__JJK.state);
  console.log('wave', w, 'spawned', before);
  // kill all regulars, and boss if present
  const kinds = await page.evaluate(()=>window.__JJK.enemies().map(e=>e.type));
  for (const k of new Set(kinds)) {
    for (let i=0;i<30;i++) {
      const found = await page.evaluate((t)=>window.__JJK.hit(t), k);
      if (!found) break;
      await page.waitForTimeout(30);
    }
  }
  await page.waitForTimeout(1400);
  console.log('wave', w, 'after kill', await page.evaluate(()=>({state:window.__JJK.state, enemies:window.__JJK.enemies(), result:document.querySelector('#result').className, banner:document.querySelector('#wave-banner').className})));
  if (w < 5) {
    await page.waitForTimeout(2800);
    console.log('wave', w, 'next', await page.evaluate(()=>window.__JJK.state));
  }
}
await page.waitForTimeout(2200);
console.log('final', await page.evaluate(()=>({state:window.__JJK.state, result:document.querySelector('#result').className, grade:document.querySelector('#grade').textContent, title:document.querySelector('#result-title').textContent})));
await browser.close();

