import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const cfg = JSON.parse(readFileSync(join(runtime, 'linux.json'),'utf8'));
const browser = await chromium.launch({...cfg.browser.launchOptions});
const page = await browser.newPage({viewport:{width:1024,height:640}});
page.on('pageerror', e => console.log('PAGEERROR', e.message));
await page.goto('http://localhost:3002?quality=low', {waitUntil:'load'});
await page.waitForTimeout(1200);
await page.click('#start-btn');
const seen = [];
let bossShot = false;
for (let step = 0; step < 700; step++) {
  const info = await page.evaluate(()=>({state:window.__JJK.state, enemies:window.__JJK.enemies(), result:document.querySelector('#result').classList.contains('is-visible')}));
  if (!seen.includes(info.state.wave) && info.state.wave > 0) seen.push(info.state.wave);
  if (info.enemies.some(e=>e.type==='boss' && !e.dead) && !bossShot) {
    await page.waitForTimeout(800);
    await page.screenshot({path:'screenshots/boss-live.png'});
    bossShot = true;
    console.log('boss screenshot', info.state);
  }
  if (info.result) {
    console.log('RESULT after', step*200, 'ms wall');
    console.log(await page.evaluate(()=>({state:window.__JJK.state, title:document.querySelector('#result-title').textContent, grade:document.querySelector('#grade').textContent})));
    break;
  }
  await page.evaluate(()=>{ for (const t of ['grunt','brute','boss']) window.__JJK.hit(t); });
  await page.waitForTimeout(180);
  if (step === 699) console.log('timeout', info.state);
}
console.log('waves seen', seen);
await page.screenshot({path:'screenshots/victory-real.png'});
console.log('final result visible', await page.evaluate(()=>document.querySelector('#result').classList.contains('is-visible')));
await browser.close();

