import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium, devices } = require('playwright');
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const cfg = JSON.parse(readFileSync(join(runtime, 'linux.json'),'utf8'));
const browser = await chromium.launch({...cfg.browser.launchOptions});
const page = await browser.newPage({viewport:{width:390,height:844}, deviceScaleFactor:1, isMobile:true, hasTouch:true, userAgent: devices['iPhone 13'].userAgent});
page.on('pageerror', e => console.log('PAGEERROR', e.message));
await page.goto('http://localhost:3002?quality=low', {waitUntil:'load', timeout:60000});
await page.waitForTimeout(1800);
await page.tap('#start-btn');
await page.waitForTimeout(600);
await page.evaluate(()=>{ window.__JJK.teleport(0,10); window.__JJK.spawnAt('boss',0,-3); });
await page.waitForTimeout(1800);
console.log('boss', await page.evaluate(()=>({state:window.__JJK.state, panel:document.querySelector('#boss-panel').className, rect:(()=>{const r=document.querySelector('#boss-panel').getBoundingClientRect(); return {x:r.x,y:r.y,w:r.width,h:r.height};})()})));
await page.screenshot({path:'screenshots/mobile-boss.png', timeout:30000});
// verify touch ultimate button and attack button change state
await page.evaluate(()=>window.__JJK.addEnergy());
await page.tap('#m-ultimate');
await page.waitForTimeout(200);
console.log('after ultimate', await page.evaluate(()=>window.__JJK.state));
await page.tap('[data-action="attack"]');
await page.waitForTimeout(300);
console.log('after attack', await page.evaluate(()=>window.__JJK.state));
await browser.close();

import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
