process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const cfg = JSON.parse(readFileSync(join(runtime, 'linux.json'),'utf8'));
const browser = await chromium.launch({...cfg.browser.launchOptions});
const page = await browser.newPage({viewport:{width:1280,height:800}});
const errors = [];
page.on('pageerror', e => errors.push(e.message));
await page.goto('http://localhost:3002?quality=low', {waitUntil:'load', timeout:60000});
await page.waitForTimeout(1200);
await page.click('#start-btn');
await page.waitForTimeout(600);
// real death path
await page.evaluate(()=>{ window.__JJK.setHealth(0); window.__JJK.damage(10); });
await page.waitForTimeout(1500);
console.log('death', await page.evaluate(()=>({state:window.__JJK.state, visible:document.querySelector('#result').classList.contains('is-visible'), title:document.querySelector('#result-title').textContent, grade:document.querySelector('#grade').textContent})));
await page.screenshot({path:'screenshots/defeat-real.png'});
// retry path
await page.click('#retry-btn');
await page.waitForTimeout(800);
console.log('retry', await page.evaluate(()=>({state:window.__JJK.state, result:document.querySelector('#result').className, menu:document.querySelector('#menu').className})));
// menu path
await page.click('#pause-btn');
await page.waitForTimeout(250);
await page.click('#quit-btn');
await page.waitForTimeout(600);
console.log('menu return', await page.evaluate(()=>({state:window.__JJK.state, menu:document.querySelector('#menu').className, hud:document.querySelector('#hud').className, mobile:getComputedStyle(document.querySelector('#mobile-controls')).display})));
// keyboard start and pause/resume
