:root {
  --ink: #06060b;
  --ink-soft: #0c0c15;
  --paper: #f1e7d6;
  --dim: #948e9e;
  --red: #ff284c;
  --red-deep: #8e1028;
  --gold: #e8bc76;
  --cyan: #69dcff;
  --violet: #a367ff;
  --hud: rgba(9, 9, 15, 0.74);
  --line: rgba(242, 232, 214, 0.18);
  --bebas: 'Bebas Neue', Impact, sans-serif;
  --raj: 'Rajdhani', 'Segoe UI', sans-serif;
}

* { box-sizing: border-box; }
html, body {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--paper);
  font-family: var(--raj);
  overscroll-behavior: none;
  -webkit-user-select: none;
  user-select: none;
}
body { touch-action: none; }

button { font: inherit; color: inherit; cursor: pointer; }
.hidden { display: none !important; }

#game-canvas {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  outline: none;
  background: #05050a;
}

#vignette {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 3;
  background:
    radial-gradient(ellipse at center, transparent 42%, rgba(2, 2, 7, 0.22) 76%, rgba(2, 2, 7, 0.68) 100%),
    linear-gradient(180deg, rgba(0,0,0,.42), transparent 18%, transparent 78%, rgba(0,0,0,.6));
}
#film-grain {

  transform: rotate(45deg);
  text-shadow: 0 0 24px var(--red);
  animation: markPulse 2s ease-in-out infinite;
}
.loader-mark::first-letter { transform: rotate(-45deg); }
@keyframes markPulse { 50% { box-shadow: 0 0 34px rgba(255,40,76,.2), inset 0 0 20px rgba(255,40,76,.1); border-color: rgba(255,40,76,.8); } }
.loader-copy { display: flex; flex-direction: column; gap: 10px; align-items: center; font-size: 10px; letter-spacing: .36em; color: #a7a0af; }
.loader-line { width: 230px; height: 2px; background: rgba(255,255,255,.12); overflow: hidden; }
.loader-line i { display: block; height: 100%; width: 38%; background: var(--red); animation: load 1.4s cubic-bezier(.6,0,.2,1) infinite; box-shadow: 0 0 12px var(--red); }
@keyframes load { 0% { transform: translateX(-120%); } 100% { transform: translateX(320%); } }

/* ======================= SCREENS ======================= */
.screen {
  position: fixed;
  inset: 0;
  z-index: 30;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity .5s ease, visibility .5s ease;
}
.screen.is-visible {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}
.modal-screen.is-visible { z-index: 60; }

/* ======================= MENU ======================= */
#menu {
  display: flex;
  flex-direction: column;
  justify-content: center;
  background:
    linear-gradient(90deg, rgba(3,3,8,.94) 0%, rgba(3,3,8,.72) 38%, rgba(3,3,8,.05) 72%),
    linear-gradient(180deg, rgba(3,3,8,.62), transparent 28%, transparent 70%, rgba(3,3,8,.9));
  overflow: hidden;
}
#menu::before {
  content: '';
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at 70% 46%, transparent 10%, rgba(5,5,10,.3) 60%, rgba(5,5,10,.88));
  pointer-events: none;
}
#menu::after {
  content: '呪';
  position: absolute;
  right: 8vw;
  top: 40%;
  transform: translateY(-50%) rotate(3deg);
  font-family: serif;
  font-size: min(50vw, 600px);
  line-height: 1;
  color: transparent;
  -webkit-text-stroke: 1px rgba(255, 40, 76, .1);
  pointer-events: none;
}
.menu-rail { position: absolute; top: 0; bottom: 0; width: 1px; background: linear-gradient(transparent, rgba(255,40,76,.35), transparent); }
.menu-rail.left { left: 34px; }
.menu-rail.right { right: 34px; }
.menu-rail::before, .menu-rail::after { content: ''; position: absolute; width: 5px; height: 5px; background: var(--red); border-radius: 50%; box-shadow: 0 0 10px var(--red); }
.menu-rail::before { top: 16%; left: -2px; }
.menu-rail::after { bottom: 14%; left: -2px; }

