import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const cfg = JSON.parse(readFileSync(join(runtime, 'linux.json'),'utf8'));
const browser = await chromium.launch({...cfg.browser.launchOptions});
const page = await browser.newPage({viewport:{width:1024,height:640}});
page.on('pageerror', e => console.log('PAGEERROR', e.message));
await page.goto('http://localhost:3002?quality=low', {waitUntil:'load', timeout:60000});
await page.waitForTimeout(1000);
await page.click('#start-btn');
await page.waitForTimeout(700);
console.log('hud pointer', await page.evaluate(()=>getComputedStyle(document.querySelector('#hud')).pointerEvents));
await page.evaluate(()=>{
  window.__clicks = 0;
  document.querySelector('#game-canvas').addEventListener('mousedown',()=>window.__clicks++);
  window.__JJK.teleport(0, 9);
  window.__JJK.spawnAt('grunt', 0, 6.8);
});
await page.waitForTimeout(800);
console.log('before', await page.evaluate(()=>({elapsed:window.__JJK.game.elapsed, hp:window.__JJK.enemies().find(e=>e.type==='grunt')?.hp, player:window.__JJK.player.pos, attack:window.__JJK.player.attack})));
await page.mouse.click(512,320);
console.log('immediate', await page.evaluate(()=>({clicks:window.__clicks, elapsed:window.__JJK.game.elapsed, cooldown:window.__JJK.player.cooldown, attack:window.__JJK.player.attack?.kind, locks:!!document.pointerLockElement})));
await page.waitForTimeout(1200);
console.log('after 1.2s', await page.evaluate(()=>({clicks:window.__clicks, elapsed:window.__JJK.game.elapsed, hp:window.__JJK.enemies().find(e=>e.type==='grunt')?.hp, attack:window.__JJK.player.attack, score:window.__JJK.game.score, combo:window.__JJK.player.combo})));
await page.waitForTimeout(2500);
console.log('after 3.7s', await page.evaluate(()=>({clicks:window.__clicks, elapsed:window.__JJK.game.elapsed, hp:window.__JJK.enemies().find(e=>e.type==='grunt')?.hp, attack:window.__JJK.player.attack, score:window.__JJK.game.score, combo:window.__JJK.player.combo})));
await page.screenshot({path:'screenshots/clicktest.png'});
await browser.close();

