import { createRequire } from 'node:module';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium, devices } = require('playwright');
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim();
const cfg = JSON.parse(readFileSync(join(runtime, 'linux.json'),'utf8'));
const browser = await chromium.launch({...cfg.browser.launchOptions});
const errors = [];
const page = await browser.newPage({viewport:{width:390,height:844}, isMobile:true, hasTouch:true, userAgent: devices['iPhone 13'].userAgent});
page.on('pageerror', e => errors.push(e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()); });
await page.goto('http://localhost:3002?quality=low', {waitUntil:'load', timeout:60000});
await page.waitForTimeout(1600);
await page.tap('#start-btn');
await page.waitForTimeout(700);
await page.evaluate(()=>window.__JJK.end(false));
await page.waitForTimeout(1700);
console.log('mobile death', await page.evaluate(()=>({state:window.__JJK.state, visible:document.querySelector('#result').classList.contains('is-visible'), card:(()=>{const r=document.querySelector('.result-card').getBoundingClientRect(); return {x:r.x,y:r.y,w:r.width,h:r.height};})()})));
await page.screenshot({path:'screenshots/mobile-result.png', timeout:30000});
// pause via touch
await page.tap('#retry-btn');
await page.waitForTimeout(800);
await page.tap('#pause-btn');
await page.waitForTimeout(500);
console.log('mobile pause', await page.evaluate(()=>({state:window.__JJK.state, pause:document.querySelector('#pause').className, card:(()=>{const r=document.querySelector('.modal-card').getBoundingClientRect(); return {x:r.x,y:r.y,w:r.width,h:r.height};})()})));
await page.screenshot({path:'screenshots/mobile-pause.png', timeout:30000});

// landscape
const lp = await browser.newPage({viewport:{width:844,height:390}, isMobile:true, hasTouch:true, userAgent: devices['iPhone 13'].userAgent});
lp.on('pageerror', e => errors.push('landscape: ' + e.message));
